            // Get the PID segment from the HL7 message
            var pidSegment = msg.get("PID");

            // Extract patient demographics (e.g., name, date of birth, sex)
            var patientName = pidSegment.get(5).getValue();
            var dateOfBirth = pidSegment.get(7).getValue();
            var sex = pidSegment.get(8).getValue();

