        Date now = new Date();
        long currentTimeMillis = now.getTime();

        if (currentTimeMillis - lastSendTime > RATE_LIMIT * 60_000L) { // 1 minute in milliseconds
            sendingFacilityRates.put(facilityId, currentTimeMillis);
            return false;
        }

        return true;
    }
}

class RateLimitException extends Exception {
    public RateLimitException(String message) {
        super(message);
    }
}
