            stmt.setObject(2, message.getPayload());
            stmt.executeUpdate();
        } catch (SQLException e) {
            throw new Exception("Error storing message in database: " + e.getMessage());
        } finally {
            conn.close();
        }
    }

    @Override
    public void stop() {}
}
