            String observationId = (String) entry.getKey();
            String observationValue = (String) entry.getValue();

            // Add each observation to the key-value map with a unique identifier
            keyValueMap.put(observationId + "_value", observationValue);
        }

        // Set the transformed data as the output of this transformer
        setOutput(keyValueMap);
    }

    private Map<String, Object> parseOBXSegments(String oruSegment) {
        PipeParser parser = new PipeParser();
