// Set up variables for tracking failed attempts and sending to DLQ
var maxFailedAttempts = 100;
var failedAttempts = 0;

function transform(message) {
    // Check if this is a new message or an existing one that's been processed before
    if (message.getMetaData('processed')) {
        // If it's already been processed, increment the failed attempts counter
        failedAttempts++;

        // If we've reached maxFailedAttempts, send to DLQ and mark as processed
        if (failedAttempts >= maxFailedAttempts) {
