    try {
        Connection conn = DriverManager.getConnection(dbUrl, dbUsername, dbPassword);
        PreparedStatement stmt = conn.prepareStatement("INSERT INTO messages (message_id, payload) VALUES (?, ?)");
        stmt.setString(1, UUID.randomUUID().toString());
        stmt.setBinaryStream(2, message.getPayload(), message.getPayload().length);
