using System;
using System.Collections.Generic;

public class Hl7Parser
{
    public List<Hl7Segment> ParseMessage(string hl7Message)
    {
        var segments = new List<Hl7Segment>();
        string[] segmentParts = hl7Message.Split('~');

        for (int i = 0; i < segmentParts.Length; i++)
        {
            if (!string.IsNullOrEmpty(segmentParts[i]))
            {
                Hl7Segment segment = ParseSegment(i, segmentParts);
                segments.Add(segment);
            }
        }

        return segments;
    }

    private Hl7Segment ParseSegment(int index, string[] segmentParts)
    {
        var segment = new Hl7Segment();
        int repetitionCount = 0;

        while (index < segmentParts.Length && !string.IsNullOrEmpty(segmentParts[index]))
        {
            if (segmentParts[index].StartsWith("X"))
            {
                // Handle repeating segments
                repetitionCount++;
                index++;
            }
            else
            {
                segment.Id = segmentParts[index];
                segment.Value = string.Join("|", segmentParts.Skip(index + 1).Take(repetitionCount));
                return segment;
            }
        }

        throw new Exception("Invalid HL7 message format");
    }
}

public class Hl7Segment
{
    public string Id { get; set; }
    public string Value { get; set; }
    public int RepetitionCount { get; set; }
}
