import ca.uhn.hl7v2.model.v24.OBX;

public class HL7ORMMessageBuilder {
    public static void main(String[] args) throws HL7Exception {
        // Create a new ORM message
        MSH msh = new MSH();
        OBR obr = new OBR();

        // Set the required fields for an ORM message
        msh.getMSH_3().setValue("Sending Application");
        msh.getMSH_4().setValue("Receiving Facility");
        msh.getMSH_7().setValue(new java.util.Date());
        msh.getMSH_9().setValue("ORM^O01");

        // Set the observation request
        obr.setOBR_1("1234567890"); // Order number
        obr.setOBR_2("Observation Requested by Dr. Smith");
        obr.setOBR_3(new java.util.Date()); // Date/Time of Observation Request

        // Create an OBX segment for the observation result
        OBX obx = new OBX();
        obx.setOBX_1("NM"); // Value Type (Numeric)
