        obx.setOBX_3("Blood Pressure Reading");
        obx.setOBX_5(new java.util.Date()); // Date/Time of the observation

        // Add the OBX segment to the OBR message
        obr.addOBX(obx);

        // Print the generated HL7 v2 ORM message
        System.out.println(msh.encode());
    }
}
