                    // Handle successful acknowledgment
                    break;
                case "AE":
                    // Handle error acknowledgment
                    throw new HL7Exception("Error in original message");
                default:
                    throw new HL7Exception("Invalid processing ID");
            }
        } else {
            throw new HL7Exception("Original message is not an acknowledgment");
        }

        // Process the acknowledgment as needed (e.g., update database, send response)
    }
}
