    public static String parseMessage(String hl7Message) throws Exception {
        // Create a pattern to match HL7 v2 escape sequences
        Pattern escapePattern = Pattern.compile("\\^([\\s\\\\]+)");

        Matcher matcher = escapePattern.matcher(hl7Message);

