interface EscapeSequence {
  start: number;
  end: number;
  replacement: string;
}

function parseHL7v2(message: string): { message: string; escapeSequences: EscapeSequence[] } {
  const escapeSequences: EscapeSequence[] = [];
  let i = 0;

  while (i < message.length) {
    if (message[i] === '^') {
      // Check for consecutive escape sequences
      let j = i + 1;
      while (j < message.length && message[j] !== '\r\n' && !/[A-Z]/.test(message[j])) {
        j++;
      }
      const sequenceLength = j - i;
      if (sequenceLength > 0) {
        escapeSequences.push({
          start: i,
          end: i + sequenceLength,
          replacement: message.substring(i, j).replace(/\^/, '').trim();
        });
        i = j;
      } else {
        // Handle single-character escape sequences
        const replacement = message[i].toUpperCase().trim();
        escapeSequences.push({
          start: i,
          end: i + 1,
          replacement: replacement,
        });
        i++;
      }
    } else {
      i++;
    }
  }

  let resultMessage = '';
  for (const sequence of escapeSequences) {
    resultMessage += message.substring(0, sequence.start);
    resultMessage += sequence.replacement;
    message = message.substring(sequence.end);
  }
  return { message: resultMessage, escapeSequences };
}
