    const promises = fhirResources.map(async (resource, index) => {
      const response = await axios.post(
        'https://your-fhir-server.com/fhir',
        { resource: JSON.stringify(resource) },
        {
          headers: {
            'Content-Type': 'application/json+fhir',
            'Prefer': 'respond-async'
          }
        }
      );

      console.log(`Resource ${index + 1} sent successfully. Status code: ${response.status}`);
    });

    // Wait for all promises to resolve
    await Promise.all(promises);
    console.log('All FHIR resources processed successfully.');
  } catch (error) {
    console.error('Error processing FHIR batch:', error);
  }
}

async function loadFhirResources() {
  const file = 'path/to/fhir/resources.json';
  const data = fs.readFileSync(file, 'utf8');
  return JSON.parse(data).map((resource) => resource.resource);
}
```

