    // Parse the XML response using xml2js
    const parser = new xml2js.Parser();
    return parser.parseString(xmlResponse, (err, result) => {
      if (err) throw err;
      const encounters = [];
      for (const entry of result.entry) {
        if (entry.resource && entry.resource.type === 'Encounter') {
          encounters.push(entry.resource);
        }
      }
      return encounters;
    });
