public class FhirClient
{
    private readonly HttpClient _httpClient;
    private readonly string _baseUrl = "https://your-meditech-fhir-api-url.com/fhir";

    public FhirClient()
    {
        _httpClient = new HttpClient();
        _httpClient.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));
    }

    public async Task<T> GetResourceAsync<T>(string resourceType, string id)
    {
        var request = new HttpRequestMessage(HttpMethod.Get, $"{_baseUrl}/{resourceType}/{id}");
        var response = await _httpClient.SendAsync(request);

        if (response.StatusCode == HttpStatusCode.OK)
        {
            return await response.Content.ReadAsJsonAsync<T>();
        }
        else
        {
            throw new Exception($"Failed to retrieve resource: {response.StatusCode}");
        }
    }

    public async Task<T> PostResourceAsync<T>(string resourceType, T resource)
    {
        var request = new HttpRequestMessage(HttpMethod.Post, $"{_baseUrl}/{resourceType}");
        request.Content = new StringContent(JsonConvert.SerializeObject(resource), "application/json");

        var response = await _httpClient.SendAsync(request);

        if (response.StatusCode == HttpStatusCode.Created)
        {
            return await response.Content.ReadAsJsonAsync<T>();
        }
        else
        {
            throw new Exception($"Failed to create resource: {response.StatusCode}");
        }
    }

    public async Task DeleteResourceAsync(string resourceType, string id)
    {
        var request = new HttpRequestMessage(HttpMethod.Delete, $"{_baseUrl}/{resourceType}/{id}");

        await _httpClient.SendAsync(request);
    }
}
