function AStar(grid, startNode, endNode) {
  let openSet = [startNode];
  let cameFrom = {};
  let gScore = {};

  while (openSet.length > 0) {
    let currentNode = openSet[0];

    if (currentNode === endNode) break;

    for (let neighbor of grid[currentNode.x][currentNode.y].neighbors()) {
      if (!cameFrom.hasOwnProperty(neighbor)) {
        cameFrom[neighbor] = currentNode;
        gScore[neighbor] = gScore[currentNode] + heuristic(currentNode, neighbor);
        openSet.push(neighbor);
      }
    }

    let minGScore = Infinity;
    for (let node of openSet) {
      if (gScore[node] < minGScore) {
        minGScore = gScore[node];
      }
    }

    openSet.shift();
  }

  return cameFrom[endNode];
}
```

