Here's an example of how to implement an LRU (Least Recently Used) cache in TypeScript:

```typescript
interface CacheItem<T> {
  key: T;
  value: any;
  timestamp: number; // or Date object
}

class LRUCache<T> {
  private cacheMap: Map<T, CacheItem<T>>;
  private linkedList: Node<T>;

  constructor(size: number) {
    this.cacheMap = new Map();
    this.linkedList = new Node(null);
  }

  get(key: T): any | null {
    if (this.cacheMap.has(key)) {
      const item = this.cacheMap.get(key);
      // Update the timestamp
      item.timestamp = Date.now();
      return item.value;
    }
    return null;
  }

  set(key: T, value: any) {
    if (!this.cacheMap.has(key)) {
      const node = new Node(key);
      this.linkedList.next = node;
      this.cacheMap.set(key, { key, value, timestamp: Date.now() });
    } else {
      // Move the item to the end of the linked list
      const oldNode = this.cacheMap.get(key);
      if (oldNode) {
        oldNode.timestamp = Date.now();
        this.linkedList.next = oldNode;
      }
    }
  }

  evict(): T | null {
    let node: Node<T> | null = this.linkedList.prev;
    while (node && !this.cacheMap.has(node.key)) {
      node = node.prev;
    }
    if (!node) return null;

    const evictedKey = node.key;
    // Remove the item from the linked list
    this.linkedList.next = node.next;
    this.cacheMap.delete(evictedKey);

    return evictedKey;
  }

  private class Node<T> {
    key: T;
    next: Node<T> | null;

    constructor(key: T) {
      this.key = key;
      this.next = null;
    }
  }
}
```

