Here's an example of implementing the A* algorithm for finding the shortest path between two nodes:

```javascript
function Node(x, y) {
  this.x = x;
  this.y = y;
}

function AStar(startNode, endNode) {
  let openSet = [new Node(startNode.x, startNode.y)];
  let closedSet = [];

  while (openSet.length > 0) {
    let currentNode = openSet[0];

    // Check if we've reached the goal node
    if (currentNode.x === endNode.x && currentNode.y === endNode.y) {
      return true;
    }

    // Expand the current node's neighbors
    for (let i = 1; i < openSet.length; i++) {
      let neighbor = new Node(openSet[i].x, openSet[i].y);
      if (!closedSet.includes(neighbor)) {
        openSet.unshift(neighbor);
      }
    }

    // Remove the current node from the open set
    openSet.shift();

    // Move to the next node in the open set
    currentNode = openSet[0];
  }

  return false;
}
```

This implementation uses a priority queue (the `openSet` array) to always expand the most promising node first. The algorithm keeps track of the g-score, h-score, and f-score for each node to determine its priority in the open set.

