import java.util.Stack;

public class Node {
    int value;
    Node next;

    public Node(int value) {
        this.value = value;
        next = null;
    }
}

public class LinkedList {
    private Node head, tail;

    public LinkedList() {
        head = new Node(0);
        tail = head;
    }

    public void add(Node node) {
        if (node == null) return;
        Node currentTail = tail;
        tail = new Node(node.value);
        tail.next = null;
        if (currentTail != null) currentTail.next = tail;
        else head = tail;
    }
}

public class DFS {
    public static void dfs(Node node, LinkedList list) {
        Stack<Node> stack = new Stack<>();
        stack.push(node);

        while (!stack.isEmpty()) {
            Node current = stack.pop();
            if (current != null) {
                System.out.print(current.value + " ");
                for (Node child : list.getNodesFromHeadToTail(current)) {
                    stack.push(child);
                }
            } else {
                System.out.println();
            }
        }
    }

    public static LinkedList getNodes(Node node, LinkedList list) {
        Stack<Node> stack = new Stack<>();
        stack.push(node);

        while (!stack.isEmpty()) {
            Node current = stack.pop();
            if (current != null) {
                for (Node child : list.getNodesFromHeadToTail(current)) {
                    stack.push(child);
                }
            } else {
                return list;
            }
        }

        LinkedList result = new LinkedList();

        while (!stack.isEmpty()) {
            Node node = stack.pop();
            if (node != null) {
                result.add(node);
            }
        }

        return result;
    }

