function sendRequest() {
    return new Promise((resolve, reject) => {
        const req = http.request({ method: 'POST', url: destUrl }, (res) => {
            // Measure the time taken for this request
            const startTime = Date.now();
            res.on('data', (chunk) => {
                resolve({
                    responseTime: Date.now() - startTime,
                    data: chunk.toString()
                });
            });
        });

        req.on('error', (err) => {
            reject(err);
        });

        // Send the request
        req.end();

        // Wait for the response to come back before measuring time again
        setTimeout(() => {
            resolve();
        }, timeout);
    });
}

