```typescript
async function tryWithRetry<T>(func: () => Promise<T>, maxAttempts = 5, initialDelay = 1000): Promise<T> {
    let attempt = 1;
    while (attempt <= maxAttempts) {
        try {
            return await func();
        } catch (error) {
            if (error.name !== 'RETRY_LIMIT_EXCEEDED') { // custom error name
                console.error(`Error occurred: ${error}`);
                throw error; // rethrow the original error
