public class BFS {
    public static void main(String[] args) {
        // Create a queue to store nodes
        Queue<Node> queue = new LinkedList<>();

        // Initialize the starting node
        Node startNode = new Node(1);
        queue.add(startNode);

        while (!queue.isEmpty()) {
            Node current = queue.poll();

            if (current.visited) continue;

            System.out.println("Visited: " + current.value);

            // Mark this node as visited
            current.visited = true;

            // Enqueue all adjacent nodes that are not yet visited
            for (int i = 1; i <= 3; i++) { // Assuming we have a graph with 4 nodes (1-2, 2-3, 3-4)
                Node nextNode = new Node(i);
                if (!nextNode.visited) {
                    queue.add(nextNode);
                }
            }
        }
    }
}
```

