```javascript
class LRUCache {
  constructor(maxSize) {
    this.maxSize = maxSize;
    this.cacheMap = new Map();
    this.lruOrder = [];
  }

  get(key, defaultValue = undefined) {
    if (!this.cacheMap.has(key)) return defaultValue;
    const item = this.cacheMap.get(key);
    // Move the item to the end of the lruOrder array
    this.lruOrder.splice(this.lruOrder.indexOf(item), 1);
    this.lruOrder.push(item);
    return item.value;
  }

  set(key, value) {
    if (this.cacheMap.has(key)) {
      const oldItem = this.cacheMap.get(key);
      // Move the old item to the end of the lruOrder array
      this.lruOrder.splice(this.lruOrder.indexOf(oldItem), 1);
      this.lruOrder.push(oldItem);
    }
    const newItem = { key, value };
    if (this.cacheMap.size >= this.maxSize) {
      // Remove the least recently used item from the cache
      const lruItem = this.lruOrder.shift();
      delete this.cacheMap[lruItem.key];
    }
    this.cacheMap.set(key, newItem);
    return true;
  }

  clear() {
    this.cacheMap.clear();
    this.lruOrder = [];
  }
}
```

