```csharp
using System;
using System.Collections.Generic;

public class Node
{
    public int value;
    public List<Node> neighbors = new List<Node>();

    public Node(int value)
    {
        this.value = value;
    }
}

public class BFSAlgorithm
{
    private Queue<Node> queue;

    public BFSAlgorithm(Node startNode)
    {
        queue = new Queue<Node>();
        queue.Enqueue(startNode);
    }

    public void Traverse(Node node, Action<Node> visitAction)
    {
        if (node == null) return;

        visitAction(node);

        foreach (var neighbor in node.neighbors)
        {
            if (!queue.Contains(neighbor))
            {
                queue.Enqueue(neighbor);
            }
        }
    }

    public void StartTraversal(Node startNode, Action<Node> visitAction)
    {
        queue.Enqueue(startNode);
        while (queue.Count > 0)
        {
            Node current = queue.Dequeue();
            Traverse(current, visitAction);
        }
    }
}
```

