}

function aStar(nodeStart: Node, nodeGoal: Node) {
  const openList = [nodeStart];
  const closedSet = new Set();

  while (openList.length > 0) {
    let currentNode = openList[0];

    if (currentNode.x === nodeGoal.x && currentNode.y === nodeGoal.y) {
      return currentNode;
    }

    // Expand the current node
    for (let neighbor of getNeighbors(currentNode)) {
      const tentativeGScore = currentNode.g + Math.abs(neighbor.x - currentNode.x) + Math.abs(neighbor.y - currentNode.y);
      if (!closedSet.has(neighbor)) {
        openList.push({ ...neighbor, f: tentativeGScore });
      }
    }

    // Move the current node to the closed set
    const currentIndex = openList.findIndex((node) => node === currentNode);
    openList.splice(currentIndex, 1);
    closedSet.add(currentNode);

    // Select the next node with the lowest f-score
    let minF = Infinity;
    let selectedNode: Node | null = null;
    for (let i = 0; i < openList.length; i++) {
