    // Move the selected node to the front of the open list
    const selectedIndex = openList.findIndex((node) => node === selectedNode);
    if (selectedIndex > 0) {
      openList.unshift(selectedNode);
    } else {
      openList.push(selectedNode);
    }
  }

  throw new Error("No path found");
}

