Here's an example of implementing Dijkstra's algorithm in TypeScript:

```typescript
interface Node {
  id: number;
  weight: number;
}

type Edge = { from: Node, to: Node, weight: number };

function dijkstra(nodes: Node[], edges: Edge[]) {
  const distances = new Map<number, number>();
  const previousNodes = new Map<number, Node>();

  nodes.forEach((node) => {
    distances.set(node.id, node.weight);
  });

  while (true) {
    let minDistance = Infinity;
    let currentNodeId: number | null = null;

    for (const [nodeId, distance] of distances.entries()) {
      if (distance < minDistance) {
        minDistance = distance;
        currentNodeId = nodeId;
      }
    }

    if (!currentNodeId) break;

    const currentNode = nodes.find((n) => n.id === currentNodeId);

    for (const edge of edges.filter((e) => e.from.id === currentNodeId)) {
      const neighborId = edge.to.id;
      const newDistance = distances.get(currentNodeId)! + edge.weight;

      if (!distances.has(neighborId) || newDistance < distances.get(neighborId)!) {
        distances.set(neighborId, newDistance);
        previousNodes.set(neighborId, currentNode);
      }
    }

    distances.delete(currentNodeId);

    if (currentNodeId === nodes.find((n) => n.id === "target")?.id) break;
  }

  const path = [];
  let currentNodeId: number | null = null;

  while (true) {
    if (!previousNodes.has(currentNodeId)) break;

    const previousNode = previousNodes.get(currentNodeId)!;
    path.unshift(previousNode);

    if (currentNodeId === nodes.find((n) => n.id === "source")?.id) break;

    currentNodeId = previousNodes.get(currentNodeId);
  }

  return { distances: [...distances], path };
}
```

This implementation uses a priority queue to keep track of the minimum distance node. It iterates until all nodes have been processed, and then reconstructs the shortest path by following the `previousNodes` map.

Note that this is an O(n^2) complexity algorithm because it scans through the edges for each node in the worst case scenario.

