    {
        distance = d;
        neighbors = n;
    }
}

public class DijkstraAlgorithm
{
    private static void Main(string[] args)
    {
        // Create a graph with 4 nodes and edges
        List<Node> graph = new List<Node>();
        for (int i = 0; i < 4; i++)
            graph.Add(new Node(int.MaxValue, new List<Node>()));

        graph[0].neighbors.Add(graph[1]);
        graph[0].neighbors.Add(graph[2]);

        graph[1].neighbors.Add(graph[3]);
        graph[2].neighbors.Add(graph[3]);

        // Initialize distances to infinity
        int[] distances = { Int32.MaxValue, Int32.MaxValue, Int32.MaxValue, Int32.MaxValue };

        // Priority queue (min-heap) with node and distance
        PriorityQueue<Node> pq = new PriorityQueue<Node>();

        // Start from node 0
        distances[0] = 0;
        pq.Enqueue(new Node(0, new List<Node>() { graph[1], graph[2] }));

        while (!pq.IsEmpty())
        {
            Node current = pq.Dequeue();

            if (current.distance > distances[current.index])
                continue;

            foreach (Node neighbor in current.neighbors)
            {
                int newDistance = current.distance + 1; // assume edge weight is 1
                if (newDistance < distances[neighbor.index])
                {
                    distances[neighbor.index] = newDistance;
                    pq.Enqueue(new Node(newDistance, new List<Node>() { neighbor }));
                }
            }
        }

        Console.WriteLine("Distances: " + string.Join(", ", distances.Select((d, i) => $"{i}: {d}")));
    }
}
```

