```typescript
interface Node {
  x: number;
  y: number;
  f: number; // g + h
  g: number;
  h: number;
}

function aStar(grid: Array<Array<number>>, start: [number, number], end: [number, number]): Node[] {
  const openList = [[start[0], start[1], 0, 0]];
  const closedList = [];

  while (openList.length > 0) {
    let node = openList[0];
    if (node.x === end[0] && node.y === end[1]) return [node];

    for (let i = 1; i < openList.length; i++) {
      if (
        Math.abs(openList[i][0] - node.x) +
          Math.abs(openList[i][1] - node.y) <
          Math.abs(node.x - openList[i][0]) + Math.abs(node.y - openList[i][1])
      ) {
        node = openList[i];
      }
    }

    for (let i = 0; i < grid.length; i++) {
      for (let j = 0; j < grid[0].length; j++) {
        if (
          !closedList.some((n) => n.x === i && n.y === j) &&
          Math.abs(i - node.x) + Math.abs(j - node.y) < 10 // heuristic
        ) {
          const g = node.g + 1;
          const h = Math.abs(i - end[0]) + Math.abs(j - end[1]);
          openList.push([i, j, g + h, g]);
          closedList.push(node);
        }
      }
    }

    return [node];
  }

  throw new Error("No path found");
}
```

