Here's an example of how to implement Dijkstra's algorithm in C#:

```csharp
using System;
using System.Collections.Generic;

public class Node
{
    public int distance { get; set; }
    public bool visited { get; set; }
    public List<Node> neighbors { get; set; }

    public Node(int d, bool v)
    {
        distance = d;
        visited = v;
        neighbors = new List<Node>();
    }
}

public class Dijkstra
{
    public static void FindShortestPath(Node sourceNode, List<Node> graph)
    {
        PriorityQueue priorityQueue = new PriorityQueue();
        sourceNode.distance = 0;
        sourceNode.visited = true;

        priorityQueue.Enqueue(sourceNode);

        while (priorityQueue.Count > 0)
        {
            Node current = priorityQueue.Dequeue() as Node;

            if (current == null) continue;

            foreach (Node neighbor in graph[current])
            {
                if (!neighbor.visited)
                {
                    neighbor.distance = current.distance + 1;
                    neighbor.visited = true;
                    priorityQueue.Enqueue(neighbor);
                }
            }
        }
    }
}
```

This implementation uses a PriorityQueue to always select the node with the smallest distance from the priority queue. The algorithm iterates until all nodes have been visited, at which point it has found the shortest path.

Note that this is an O(1) complexity implementation because each edge is processed exactly once.

