        while (i < left.Length && j < right.Length)
        {
            if ((left[i].CompareTo(right[j]) <= 0))
                array[i++] = left[i++];
            else
                array[i++] = right[j++];
        }

        for (int k = i; k < array.Length; k++)
            array[k] = left[k - i];

        for (int k = j; k < array.Length; k++)
            array[k] = right[k - j];
    }
}
