            if (!visited[i]) {
                int[] node = {i, Integer.MAX_VALUE};
                pq.add(node);
            }
        }

        while (!pq.isEmpty()) {
            int[] current = pq.poll();

            // If we've reached the destination node, break out of the loop
            if (current[0] == n - 1) {
                break;
            }

            for (int i = 0; i < n; i++) {
