                        int[] neighbor = {i, current[1] + weight};
                        pq.add(neighbor);
                    }
                }
            }

            // Mark the current node as visited
            visited[current[0]] = true;
        }

        System.out.println("Shortest distance from node 0 to node " + (n - 1) + ": " + dist[n - 1]);
    }
}
