    int right = array.Length - 1;

    while (left <= right)
    {
        int mid = (left + right) / 2;

        if (array[mid] == target)
            return mid; // Found!

        else if (array[mid] < target)
            left = mid + 1;
        else
            right = mid - 1;
    }

