    const { node: currentNode, distance: currentDistance } = heap.shift();

    if (currentDistance > distances.get(currentNode.id)) continue;

    for (const edge of edges.filter((e) => e.from.id === currentNode.id)) {
      const nextNode = edge.to;
      const newDistance = currentDistance + edge.weight;

      if (!distances.has(nextNode.id) || newDistance < distances.get(nextNode.id)) {
        distances.set(nextNode.id, newDistance);
        heap.push({ node: nextNode, distance: newDistance });
      }
    }
  }

  return [...distances.entries()].map(([id, distance]) => ({ id, distance }));
}
```

This implementation uses a priority queue (heap) to efficiently find the shortest path between nodes. The algorithm initializes distances for all nodes and then iterates over the heap until it's empty. For each node, it checks if there are any edges leading out of that node and updates the distances accordingly.

The time complexity is O((E + V) log V), where E is the number of edges and V is the number of nodes. This implementation has a constant factor overhead due to the heap operations, but overall, it's still efficient for most practical purposes.

