```csharp
using System;
using System.Collections.Generic;

public class MergeSort
{
    public static void Sort<T>(T[] array) where T : IComparable
    {
        if (array.Length <= 1)
            return;

        int mid = array.Length / 2;
        int leftMid = mid - 1;
        int rightMid = mid + 1;

        var left = new List<T>();
        for (int i = 0; i < leftMid; i++)
            left.Add(array[i]);

        var right = new List<T>();
        for (int i = rightMid; i < array.Length; i++)
            right.Add(array[i]);

        Sort(left.ToArray(), "left");
        Sort(right.ToArray(), "right");

        MergeSortHelper(left, right);
    }

    private static void MergeSortHelper(List<T> left, List<T> right)
    {
        var result = new List<T>();
        int i = 0;
        int j = 0;

        while (i < left.Count && j < right.Count)
        {
            if ((int)left[i].CompareTo(right[j]) <= 0)
                result.Add(left[i]);
            else
                result.Add(right[j]);

            i++;
            j++;
        }

        while (i < left.Count)
            result.Add(left[i]);
        while (j < right.Count)
            result.Add(right[j]);

        array = result.ToArray();
    }
}
