```java
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Dijkstra {
    private int[][] graph; // adjacency matrix
    private int n; // number of nodes

    public Dijkstra(int[][] graph, int n) {
        this.graph = graph;
        this.n = n;
    }

    public void dijkstra() {
        int[] dist = new int[n];
        boolean[] visited = new boolean[n];

        for (int i = 0; i < n; i++) {
            dist[i] = Integer.MAX_VALUE;
            visited[i] = false;
        }

        dist[0] = 0;

        PriorityQueue<Node> queue = new PriorityQueue<>();
        queue.add(new Node(0, 0));

        while (!queue.isEmpty()) {
            int currentDistance = queue.poll().distance;
            int u = queue.poll().node;

            if (visited[u]) continue;

            for (int v = 1; v < n; v++) {
                if (!visited[v] && graph[u][v] != -1) {
                    if (dist[v] > dist[u] + graph[u][v]) {
                        dist[v] = dist[u] + graph[u][v];
                        visited[v] = true;
                        queue.add(new Node(dist[v], v));
                    }
                }
            }
        }

        System.out.println("Shortest distances: " + java.util.Arrays.toString(dist));
    }

    public static class Node implements Comparable<Node> {
        int distance;
        int node;

        public Node(int distance, int node) {
            this.distance = distance;
            this.node = node;
        }

        @Override
        public int compareTo(Node other) {
            return Integer.compare(distance, other.distance);
        }
    }
}
```

This implementation uses a priority queue to always expand the shortest path first. The `dijkstra()` method takes an adjacency matrix as input and computes the shortest distances from node 0 to all other nodes.

Note that this implementation assumes that the graph is directed (i.e., edges have direction), but you can modify it to handle undirected graphs by removing the condition `if (!visited[v] && graph[u][v] != -1)` in the inner loop.

