**LRUCache Class**
```java
import java.util.HashMap;
import java.util.Map;

public class LRUCache {
    private int maxCapacity; // Maximum capacity of the cache
    private Map<String, String> cacheMap; // Cache map to store key-value pairs

    public LRUCache(int maxCapacity) {
        this.maxCapacity = maxCapacity;
        this.cacheMap = new HashMap<>();
    }

    public void put(String key, String value) {
        if (cacheMap.size() >= maxCapacity) {
            // If the cache is full, remove the least recently used item
            String leastRecentlyUsedKey = getLeastRecentlyUsedKey();
            cacheMap.remove(leastRecentlyUsedKey);
        }
        cacheMap.put(key, value);
    }

    public String get(String key) {
        return cacheMap.get(key);
    }

    private String getLeastRecentlyUsedKey() {
        // Find the least recently used item
        long leastRecentlyUsedTime = Long.MAX_VALUE;
        String leastRecentlyUsedKey = null;
        for (Map.Entry<String, String> entry : cacheMap.entrySet()) {
            if (entry.getValue().lastAccessed < leastRecentlyUsedTime) {
                leastRecentlyUsedTime = entry.getValue().lastAccessed;
                leastRecentlyUsedKey = entry.getKey();
            }
        }
        return leastRecentlyUsedKey;
    }

    private static class CacheItem {
        public String key; // Key of the cache item
        public long lastAccessed; // Last accessed time of the cache item

        public CacheItem(String key) {
            this.key = key;
            this.lastAccessed = System.currentTimeMillis();
        }
    }
}
