class Saga<T> {
  private _commands: Set<Command>;

  constructor() {
    this._commands = new Set();
  }

  public when(condition: boolean, handler: EventHandler<T>): void {
    if (condition) {
      const event = { type: 'event' };
      handler.handle(event).then(() => {
        // Command has been executed successfully
        this._commands.add(new Command({
          execute() {
            console.log('Command executed');
          },
          rollback() {
            console.log('Command rolled back');
          }
        }));
      }).catch((error) => {
        // Handle error
        console.error(error);
      });
    }
  }

  public execute(): Promise<void> {
    return new Promise((resolve, reject) => {
      try {
        this._commands.forEach((command: Command) => {
          command.execute();
        });
        resolve();
      } catch (error) {
        // Handle error
        console.error(error);
        reject(error);
      }
    });
  }

  public rollback(): void {
    this._commands.forEach((command: Command) => {
      command.rollback();
    });
  }
}
```

