Here's an implementation of the A* algorithm in TypeScript:
```typescript
interface Node {
  x: number;
  y: number;
  f: number; // cost to reach this node
  g: number; // cumulative cost from start node
  h: number; // heuristic estimate of distance to goal
}

function aStar(nodeStart: Node, nodeGoal: Node) {
  const openSet = [nodeStart];
  const cameFrom = {} as Record<number, number>;
  const gScore = {} as Record<number, number>;

  while (openSet.length > 0) {
    let currentNode = openSet[0];

    // Check if we've reached the goal node
    if (currentNode.x === nodeGoal.x && currentNode.y === nodeGoal.y) {
      return currentNode;
    }

    // Expand the current node's neighbors
    const neighbors = getNeighbors(currentNode);

    for (const neighbor of neighbors) {
      // Calculate the heuristic estimate of distance to goal
      const hScore = calculateH(neighbor, nodeGoal);

      // Update gScore and cameFrom if this is a better path
      if (!gScore[neighbor.x + "," + neighbor.y] || gScore[neighbor.x + "," + neighbor.y] > currentNode.g + 1) {
        cameFrom[neighbor.x + "," + neighbor.y] = currentNode.x + "," + currentNode.y;
        gScore[neighbor.x + "," + neighbor.y] = currentNode.g + 1;

        // Add to openSet and sort by f-score
        const fScore = calculateF(neighbor, nodeGoal);
        if (!openSet.includes(neighbor)) {
          openSet.push({ ...neighbor, f: fScore });
          openSet.sort((a, b) => a.f - b.f);
        }
      }
    }

    // Remove the current node from openSet
    const currentIndex = openSet.indexOf(currentNode);
    if (currentIndex !== 0) {
      openSet.splice(currentIndex, 1);
    }
  }

  return null; // goal not reached
}

function calculateH(node: Node, nodeGoal: Node): number {
  const dx = Math.abs(node.x - nodeGoal.x);
  const dy = Math.abs(node.y - nodeGoal.y);

  return Math.sqrt(dx * dx + dy * dy);
}

function calculateF(node: Node, nodeGoal: Node): number {
  return node.g + calculateH(node, nodeGoal);
}

