```csharp
using System;
using System.Collections.Generic;

public class MergeSort
{
    public static void Sort<T>(T[] array) where T : IComparable
    {
        if (array.Length <= 1)
            return;

        int mid = array.Length / 2;
        var left = new List<T>(array.Take(mid));
        var right = new List<T>(array.Skip(mid));

        Sort(left.ToArray());
        Sort(right.ToArray());

        MergeSortArray(array, left.ToArray(), right.ToArray());
    }

    private static void MergeSortArray<T>(T[] result, T[] left, T[] right) where T : IComparable
    {
        int i = 0;
        int j = 0;

        for (int k = 0; k < result.Length; k++)
        {
            if (left[j].CompareTo(right[i]) <= 0)
                result[k] = left[j++];
            else
                result[k] = right[i++];
        }
    }

    public static T[] MergeSortArray<T>(T[] array) where T : IComparable
    {
        var result = new List<T>();
        Sort(array);
        return result.ToArray();
    }
}
