Here's an example of how to implement an LRU (Least Recently Used) cache in C#:

**LRUCache.cs**
```csharp
using System;
using System.Collections.Generic;

public class LRUCache<T>
{
    private Dictionary<T, int> _cache = new Dictionary<T, int>();
    private LinkedList<T> _recentlyUsed = new LinkedList<T>();

    public T Get(T key)
    {
        if (_cache.TryGetValue(key, out int value))
        {
            // Move the item to the end of the recently used list
            _recentlyUsed.Remove(value);
            _recentlyUsed.AddLast(value);

            return (T)_cache[key];
        }
        else
        {
            throw new KeyNotFoundException("Item not found in cache");
        }
    }

    public void Put(T key, T value)
    {
        if (_cache.ContainsKey(key))
        {
            // Move the item to the end of the recently used list
            _recentlyUsed.Remove(key);
            _recentlyUsed.AddLast(key);

            _cache[key] = value;
        }
        else
        {
            // Add new item at the end of the recently used list
            _recentlyUsed.Add(key);
            _cache.Add(key, value);
        }
    }

    public int Count => _cache.Count;

    public bool Contains(T key)
    {
        return _cache.ContainsKey(key);
    }
}
```
