function dijkstra(graph, startNode) {
  const distances = new Map();
  const visited = new Set();

  // Initialize distances and mark node as visited
  for (let i = 0; i < graph.length; i++) {
    if (!visited.has(i)) {
      distances.set(i, Infinity);
      visited.add(i);
    }
  }

  // Priority queue (min-heap) to store nodes with their distances
  const heap = [];

  // Start node is always at distance 0
  pushToHeap(startNode, 0);

  while (heap.length > 0) {
    let currentDistance;
    let currentNode;

    // Extract the node with the smallest distance from the heap
    [currentDistance, currentNode] = heappop(heap);

    if (!visited.has(currentNode)) continue; // Skip if not visited

    for (let neighbor of graph[currentNode]) {
      const newDistance = currentDistance + 1; // Assuming edge weights are 1

      if (newDistance < distances.get(neighbor)) { // Update distance if shorter path found
        distances.set(neighbor, newDistance);
        pushToHeap(neighbor, newDistance); // Add to heap for further processing
      }
    }

    visited.add(currentNode); // Mark node as visited once processed
  }

  return distances;
}

function heappush(heap, [distance, node]) {
  const length = heap.length;

  if (length === 0 || distance < heap[length - 1][0]) {
    heap.push([distance, node]);
  } else {
    for (let i = length; i > 0; i--) {
      if (heap[i - 1][0] > distance) break;
      heappush(heap, [heap[i - 1][0], heap[i - 1][1]]);
    }
    heap.push([distance, node]);
  }

  heap.sort((a, b) => a[0] - b[0]);
}

function heappop(heap) {
  if (heap.length === 0) throw new Error("Heap is empty");

  return heap.shift();
}
