```java
import java.util.HashMap;
import java.util.Map;

public class LRUCache {
    private int maxCapacity;
    private Map<String, String> cacheMap;

    public LRUCache(int maxCapacity) {
        this.maxCapacity = maxCapacity;
        this.cacheMap = new HashMap<>();
    }

    public void put(String key, String value) {
        if (cacheMap.size() >= maxCapacity) {
            // Remove the least recently used item
            String leastRecentlyUsedKey = getLeastRecentlyUsedKey();
            cacheMap.remove(leastRecentlyUsedKey);
        }
        cacheMap.put(key, value);
    }

    private String getLeastRecentlyUsedKey() {
        long currentTimeMillis = System.currentTimeMillis();
        int maxAge = 1000; // adjust this to your desired cache expiration time
        Map.Entry<String, String> leastRecentlyUsedEntry = null;
        for (Map.Entry<String, String> entry : cacheMap.entrySet()) {
            if ((currentTimeMillis - Long.parseLong(entry.getValue().split(":")[1])) > maxAge) {
                leastRecentlyUsedEntry = entry;
                break;
            }
        }
        return leastRecentlyUsedEntry.getKey();
    }

    public String get(String key) {
        return cacheMap.get(key);
    }
}
```

