```javascript
const express = require('express');
const app = express();
app.use(express.json());

// Define the validation schema for our resource
const resourceSchema = {
  type: 'object',
  properties: {
    name: { type: 'string' },
    age: { type: 'integer' }
  },
  required: ['name', 'age']
};

// Create an endpoint to validate resources
app.post('/validate', (req, res) => {
  const resource = req.body;

  // Validate the resource against our schema
  try {
    const validator = require('json-schema-validator');
    const validatedResource = validator.validate(resource, resourceSchema);

    if (!validatedResource.errors.length) {
      res.status(200).send({ message: 'Resource is valid' });
    } else {
      res.status(400).send(validatedResource.errors.map(error => error.message));
    }
  } catch (error) {
    res.status(500).send('Error validating resource');
  }
});

// Start the server
const port = 3000;
app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
});
```

In this example, we define a schema for our resource using JSON Schema syntax. Then, in our Express endpoint, we use the `json-schema-validator` library to validate the incoming request body against that schema.

If the validation passes without any errors, we return a 200 OK response with a message indicating that the resource is valid. If there are any validation errors, we return a 400 Bad Request response with an array of error messages.

Note that this example assumes you're working with JSON data and using the `json` middleware to parse the request body as JSON. You may need to modify it depending on your specific use case.

